{
  "apiVersion": 1,
  "type": "component.detail.props",
  "package": "@astryxdesign/core",
  "data": [
    {
      "name": "label",
      "type": "string",
      "description": "Label text.",
      "required": true
    },
    {
      "name": "isLabelHidden",
      "type": "boolean",
      "description": "Visually hide the label.",
      "default": "false"
    },
    {
      "name": "description",
      "type": "string",
      "description": "Helper text displayed below the label."
    },
    {
      "name": "isOptional",
      "type": "boolean",
      "description": "Show an \"(optional)\" indicator next to the label.",
      "default": "false"
    },
    {
      "name": "isRequired",
      "type": "boolean",
      "description": "Mark the field as required.",
      "default": "false"
    },
    {
      "name": "isDisabled",
      "type": "boolean",
      "description": "Disable the input and picker. The fields stay focusable and expose `aria-disabled`; typing and opening are blocked.",
      "default": "false"
    },
    {
      "name": "disabledMessage",
      "type": "string",
      "description": "Explains why the input is disabled. With isDisabled, shows a tooltip on hover/keyboard focus and describes the fields (activation stays blocked). Use this instead of wrapping a disabled DateTimeInput in Tooltip."
    },
    {
      "name": "value",
      "type": "ISODateTimeString",
      "description": "Selected datetime in ISO 8601 format (YYYY-MM-DDTHH:MM or YYYY-MM-DDTHH:MM:SS)."
    },
    {
      "name": "onChange",
      "type": "(value: ISODateTimeString | undefined) => void",
      "description": "Callback invoked when the selected datetime changes.",
      "required": true
    },
    {
      "name": "changeAction",
      "type": "(value: ISODateTimeString | undefined) => void | Promise<void>",
      "description": "Async action fired after onChange. Drives optimistic UI updates via useTransition."
    },
    {
      "name": "isLoading",
      "type": "boolean",
      "description": "Whether the input is in a loading state. Disables interaction and shows a spinner.",
      "default": "false"
    },
    {
      "name": "min",
      "type": "ISODateTimeString",
      "description": "Minimum selectable datetime. Constrains both date and time selection."
    },
    {
      "name": "max",
      "type": "ISODateTimeString",
      "description": "Maximum selectable datetime. Constrains both date and time selection."
    },
    {
      "name": "dateConstraints",
      "type": "Array<(date: Date) => boolean>",
      "description": "Array of custom constraint functions that disable specific dates."
    },
    {
      "name": "hasSeconds",
      "type": "boolean",
      "description": "Include seconds in the time portion. Keeps Astryx's time field even when nativePicker selects native surfaces, because iOS has no seconds wheel.",
      "default": "false"
    },
    {
      "name": "hourFormat",
      "type": "'12h' | '24h'",
      "description": "Hour display format. '12h' shows the locale's day period; '24h' uses 24-hour notation. When unset, follows the InternationalizationProvider locale's hour cycle (en-US 12-hour, en-GB 24-hour); a person's own preference rides on the locale tag (e.g. 'en-US-u-hc-h23').",
      "default": "the locale's hour cycle"
    },
    {
      "name": "timeIncrement",
      "type": "1 | 5 | 10 | 15 | 30",
      "description": "Minute step for arrow keys in Astryx's typed time field. A non-default value keeps the Astryx time field in nativePicker modes because iOS treats native step as validation, not picker cadence. Ignored by the Astryx touch sheet, which uses wheels.",
      "default": "1"
    },
    {
      "name": "timeOptionInterval",
      "type": "5 | 10 | 15 | 30 | 60",
      "description": "Minute cadence for the preset-time combobox on Astryx's fine-pointer time field. Setting it keeps that Astryx time field even in nativePicker modes because the OS picker has no equivalent preset list. The Astryx touch sheet uses wheels."
    },
    {
      "name": "hasClear",
      "type": "boolean",
      "description": "Shows a clear button when a datetime value is set.",
      "default": "false"
    },
    {
      "name": "placeholder",
      "type": "string",
      "description": "Placeholder text shown in the date portion when no date is selected. A caller placeholder replaces the calendar format hint.",
      "default": "'Select a date'"
    },
    {
      "name": "calendar",
      "type": "'gregory' | 'iso8601' | 'buddhist' | 'roc' | 'japanese' | 'persian' | 'indian' | 'hebrew' | 'chinese' | 'dangi' | 'coptic' | 'ethiopic' | 'ethioaa' | 'islamic-civil' | 'islamic-tbla' | 'islamic-umalqura'",
      "description": "The calendar the date segment reads and writes typed dates in, and the calendar its popover and bottom sheet show. value, onChange, min, and max stay Gregorian ISO datetimes. People type a date the way the locale writes it in this calendar, in any decimal digits; the field reports a date only once it is complete, and names a date the calendar does not have. Years are years of this calendar, so set min and max on Buddhist and Minguo calendar fields to catch a Gregorian year typed by mistake. Calendars other than gregory, iso8601, buddhist, roc, and japanese need Temporal, native or a polyfill the application loads; without it the field shows Gregorian dates. With a calendar other than gregory or iso8601, a presentation that would show native controls shows the popovers on a fine pointer and the bottom sheet on a coarse pointer, because the native date control is Gregorian; the Date panel of the bottom sheet shows the months, leap months, and era years of the calendar. A year in which the era changes is labeled with the era of the shown month, such as 平成31 in January 2019 and 令和元 in July.",
      "default": "the InternationalizationProvider's calendar, else 'gregory'"
    },
    {
      "name": "timePlaceholder",
      "type": "string",
      "description": "Placeholder text shown in the time portion when no time is selected. On touch, this appears in the closed time segment before a time is chosen.",
      "default": "'Select a time'"
    },
    {
      "name": "timeLabel",
      "type": "string",
      "description": "Accessible label for the time portion. Defaults to \"{label} time\" so it is tied to the field label and localizable."
    },
    {
      "name": "size",
      "type": "'sm' | 'md' | 'lg'",
      "description": "Size of the input control.",
      "default": "'md'"
    },
    {
      "name": "status",
      "type": "{type: 'warning' | 'error' | 'success', message?: string}",
      "description": "Status indicator object for error, warning, or success states with a message."
    },
    {
      "name": "labelTooltip",
      "type": "string",
      "description": "Tooltip text displayed via an info icon at the end of the label."
    },
    {
      "name": "numberOfMonths",
      "type": "1 | 2",
      "description": "Number of months displayed simultaneously in Astryx's pointer calendar popover. Ignored by native date controls and the mobile touch sheet, whose Date panel always shows one swipe-paged month at a time.",
      "default": "1"
    },
    {
      "name": "weekStartsOn",
      "type": "0 | 1 | 2 | 3 | 4 | 5 | 6 | 'sun' | 'mon' | 'tue' | 'wed' | 'thu' | 'fri' | 'sat'",
      "description": "First day of week in Astryx calendars. A number (0 = Sunday to 6 = Saturday) or a three-letter day name. Ignored by native date controls.",
      "default": "0"
    },
    {
      "name": "presentation",
      "type": "'popover' | 'bottom-sheet' | 'native' | 'adaptive-bottom-sheet' | 'adaptive-native'",
      "description": "Which surfaces draw the date and time pickers. 'adaptive-native' (the default) uses Astryx's typed fields and popovers on a fine pointer and browser/OS controls on a coarse pointer — with per-segment Astryx fallbacks: hasSeconds, non-default timeIncrement, or timeOptionInterval retain Astryx's time field because iOS cannot express them faithfully; 'native' always uses both browser/OS controls with no fallback; 'adaptive-bottom-sheet' uses popovers on a fine pointer and Astryx's coordinated bottom sheet on a coarse pointer; 'popover' and 'bottom-sheet' force that Astryx surface on every pointer. Every value opens pickers; typed-only fields are TimeInput's alone. Use a non-native presentation when numberOfMonths, weekStartsOn, or visible dateConstraints behavior matters. Constraints are enforced on commit; min/max are forwarded as hints. hourFormat formats the closed time, while the OS picker follows the user's locale. With a calendar other than gregory or iso8601, 'native' and 'adaptive-native' use the popovers on a fine pointer and the bottom sheet on a coarse pointer, and an explicit 'native' warns in development.",
      "default": "'adaptive-native'"
    },
    {
      "name": "nativePicker",
      "type": "'touch' | 'always' | 'never'",
      "description": "Deprecated: use presentation ('touch' = 'adaptive-native', 'always' = 'native', 'never' = 'adaptive-bottom-sheet'). Still works exactly as released; presentation wins when both are set. With a calendar other than gregory or iso8601, 'touch' and 'always' use the popovers on a fine pointer and the bottom sheet on a coarse pointer.",
      "default": "'touch'"
    },
    {
      "name": "width",
      "type": "SizeValue",
      "description": "Width of the field (number = pixels, string used as-is, e.g. \"100%\"). Sizes the whole field (label, control, and status) so they stay aligned."
    },
    {
      "name": "containerXstyle",
      "type": "StyleXStyles",
      "description": "StyleX styles for the Field box around the label, control, and status. containerClassName and containerStyle take a class name and inline styles for the same box. No effect (development warning) where no Field box renders: inside InputGroup (style the group) and in a horizontal-labels FormLayout."
    },
    {
      "name": "controlXstyle",
      "type": "StyleXStyles",
      "description": "StyleX styles for the visual control box: the row that holds the bordered date and time segments with their icons and end controls, never a native input. controlClassName and controlStyle take a class name and inline styles for the same box. Replaces root xstyle, className, and style, which this component does not accept."
    }
  ],
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
